-- Dump de exemplo (MySQL) com várias chaves estrangeiras, para o diagrama do cartão "Banco de dados (.sql)"
CREATE TABLE `paises` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(80) NOT NULL, `sigla` char(2) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `sigla` (`sigla`));
CREATE TABLE `cidades` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(120) NOT NULL, `pais_id` int NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_cid_pais` FOREIGN KEY (`pais_id`) REFERENCES `paises` (`id`));
CREATE TABLE `usuarios` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(120) NOT NULL, `email` varchar(160) NOT NULL, `senha` varchar(255) NOT NULL, `criado_em` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `email` (`email`));
CREATE TABLE `perfis` (`id` int NOT NULL AUTO_INCREMENT, `usuario_id` int NOT NULL, `bio` text, `avatar` varchar(255) DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `usuario_id` (`usuario_id`), CONSTRAINT `fk_perfil_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`));
CREATE TABLE `enderecos` (`id` int NOT NULL AUTO_INCREMENT, `usuario_id` int NOT NULL, `cidade_id` int NOT NULL, `rua` varchar(160) NOT NULL, `numero` varchar(10) DEFAULT NULL, `cep` varchar(9) NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_end_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`), CONSTRAINT `fk_end_cidade` FOREIGN KEY (`cidade_id`) REFERENCES `cidades` (`id`));
CREATE TABLE `categorias` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(80) NOT NULL, `pai_id` int DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_cat_pai` FOREIGN KEY (`pai_id`) REFERENCES `categorias` (`id`));
CREATE TABLE `fornecedores` (`id` int NOT NULL AUTO_INCREMENT, `razao_social` varchar(160) NOT NULL, `cnpj` char(14) NOT NULL, `cidade_id` int DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_forn_cidade` FOREIGN KEY (`cidade_id`) REFERENCES `cidades` (`id`));
CREATE TABLE `produtos` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(160) NOT NULL, `descricao` text, `preco` decimal(10,2) NOT NULL, `estoque` int NOT NULL DEFAULT 0, `categoria_id` int NOT NULL, `fornecedor_id` int DEFAULT NULL, `ativo` tinyint(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id`), CONSTRAINT `fk_prod_cat` FOREIGN KEY (`categoria_id`) REFERENCES `categorias` (`id`), CONSTRAINT `fk_prod_forn` FOREIGN KEY (`fornecedor_id`) REFERENCES `fornecedores` (`id`));
CREATE TABLE `produto_fotos` (`id` int NOT NULL AUTO_INCREMENT, `produto_id` int NOT NULL, `url` varchar(255) NOT NULL, `ordem` int NOT NULL DEFAULT 0, PRIMARY KEY (`id`), CONSTRAINT `fk_foto_prod` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`));
CREATE TABLE `cupons` (`id` int NOT NULL AUTO_INCREMENT, `codigo` varchar(30) NOT NULL, `desconto` decimal(5,2) NOT NULL, `validade` date DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `codigo` (`codigo`));
CREATE TABLE `pedidos` (`id` int NOT NULL AUTO_INCREMENT, `usuario_id` int NOT NULL, `endereco_id` int NOT NULL, `cupom_id` int DEFAULT NULL, `status` varchar(20) NOT NULL, `total` decimal(10,2) NOT NULL, `criado_em` datetime NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_ped_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`), CONSTRAINT `fk_ped_end` FOREIGN KEY (`endereco_id`) REFERENCES `enderecos` (`id`), CONSTRAINT `fk_ped_cupom` FOREIGN KEY (`cupom_id`) REFERENCES `cupons` (`id`));
CREATE TABLE `pedido_itens` (`id` int NOT NULL AUTO_INCREMENT, `pedido_id` int NOT NULL, `produto_id` int NOT NULL, `quantidade` int NOT NULL, `preco_unit` decimal(10,2) NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_item_ped` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`), CONSTRAINT `fk_item_prod` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`));
CREATE TABLE `pagamentos` (`id` int NOT NULL AUTO_INCREMENT, `pedido_id` int NOT NULL, `metodo` varchar(20) NOT NULL, `valor` decimal(10,2) NOT NULL, `pago_em` datetime DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_pag_ped` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`));
CREATE TABLE `entregas` (`id` int NOT NULL AUTO_INCREMENT, `pedido_id` int NOT NULL, `transportadora_id` int DEFAULT NULL, `codigo_rastreio` varchar(40) DEFAULT NULL, `enviado_em` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `pedido_id` (`pedido_id`), CONSTRAINT `fk_ent_ped` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`), CONSTRAINT `fk_ent_transp` FOREIGN KEY (`transportadora_id`) REFERENCES `transportadoras` (`id`));
CREATE TABLE `transportadoras` (`id` int NOT NULL AUTO_INCREMENT, `nome` varchar(120) NOT NULL, `cidade_id` int DEFAULT NULL, PRIMARY KEY (`id`), CONSTRAINT `fk_transp_cidade` FOREIGN KEY (`cidade_id`) REFERENCES `cidades` (`id`));
CREATE TABLE `avaliacoes` (`id` int NOT NULL AUTO_INCREMENT, `produto_id` int NOT NULL, `usuario_id` int NOT NULL, `pedido_item_id` int DEFAULT NULL, `nota` tinyint NOT NULL, `comentario` text, PRIMARY KEY (`id`), CONSTRAINT `fk_av_prod` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`), CONSTRAINT `fk_av_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`), CONSTRAINT `fk_av_item` FOREIGN KEY (`pedido_item_id`) REFERENCES `pedido_itens` (`id`));
CREATE TABLE `favoritos` (`usuario_id` int NOT NULL, `produto_id` int NOT NULL, `criado_em` datetime DEFAULT NULL, PRIMARY KEY (`usuario_id`,`produto_id`), CONSTRAINT `fk_fav_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`), CONSTRAINT `fk_fav_prod` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`));
CREATE TABLE `carrinhos` (`id` int NOT NULL AUTO_INCREMENT, `usuario_id` int NOT NULL, `produto_id` int NOT NULL, `quantidade` int NOT NULL DEFAULT 1, PRIMARY KEY (`id`), CONSTRAINT `fk_car_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`), CONSTRAINT `fk_car_prod` FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`));
CREATE TABLE `logs_acesso` (`id` bigint NOT NULL AUTO_INCREMENT, `ip` varchar(45) NOT NULL, `rota` varchar(255) NOT NULL, `em` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `configuracoes` (`chave` varchar(60) NOT NULL, `valor` text, PRIMARY KEY (`chave`));
